fn make_greeting(name: String) -> impl Future<Output = String> {
    async move { format!("Hello, {name}!") } // owns name
}

fn main() {
    let names = vec![String::from("Ferris"), String::from("Corro")];
    let joined = block_on(async {
        let mut out = Vec::new();
        for n in &names {
            out.push(make_greeting(n.clone()).await);
        }
        out.join(" ")
    });
    println!("{joined}");
    println!("names still here: {}", names.len());
}

use std::future::Future;
use std::pin::{Pin, pin};
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};

struct ThreadWaker(Thread);
impl Wake for ThreadWaker {
    fn wake(self: Arc<Self>) {
        self.0.unpark();
    }
}

fn block_on<F: Future>(fut: F) -> (F::Output, u32) {
    let mut fut = pin!(fut);
    let waker = Waker::from(Arc::new(ThreadWaker(thread::current())));
    let mut cx = Context::from_waker(&waker);
    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(v) => return (v, 0), // TODO: count polls
            Poll::Pending => thread::park(),
        }
    }
}

struct YieldOnce(bool);
impl Future for YieldOnce {
    type Output = ();
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.0 {
            Poll::Ready(())
        } else {
            self.0 = true;
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    }
}

fn main() {
    let (value, polls) = block_on(async {
        YieldOnce(false).await;
        YieldOnce(false).await;
        YieldOnce(false).await;
        42
    });
    println!("value = {value} after {polls} polls");
}
